"""Retention Recommendations page: rule-based, fully local retention
suggestions for at-risk customers, with filtering by risk category."""

import streamlit as st

from risk_segmentation import build_risk_table
from retention_engine import recommendations_dataframe
from utils import RISK_ORDER


DISPLAY_COLS = ["Contract", "tenure", "MonthlyCharges", "InternetService", "PaymentMethod", "TechSupport"]


def render():
    st.title("💡 Intelligent Retention Recommendations")
    st.caption(
        "All suggestions are generated by a local, rule-based recommendation engine -- no external "
        "AI/LLM API is used. Suggestions are phrased as options to consider, never guarantees."
    )

    df = st.session_state.get("working_df")
    model = st.session_state.get("model")
    preprocessor = st.session_state.get("preprocessor")
    feature_cols = st.session_state.get("feature_cols", [])
    id_col = st.session_state.get("id_col")
    thresholds = st.session_state.get("risk_thresholds", {"low": 30, "medium": 60, "high": 80})

    if df is None:
        st.warning("Please upload and prepare a dataset first, on the **Data Upload** page.")
        return
    if model is None or preprocessor is None:
        st.warning("No active trained model. Please train and save a model on the **Model Training** page.")
        return

    display_cols = [c for c in DISPLAY_COLS if c in df.columns]
    risk_table = build_risk_table(
        df, feature_cols, preprocessor, model, id_col, thresholds, display_cols=display_cols,
    )

    st.subheader("Filter Customers")
    f1, f2 = st.columns([2, 1])
    with f1:
        risk_filter = st.multiselect("Risk categories to include", RISK_ORDER, default=["High Risk", "Critical Risk"])
    with f2:
        limit = st.number_input("Max customers to generate recommendations for", 5, 500, 50, step=5,
                                 help="Recommendation generation runs per-customer; limit keeps this page responsive on large datasets.")

    subset = risk_table[risk_table["risk_category"].isin(risk_filter)].head(int(limit))

    if subset.empty:
        st.info("No customers match the selected risk categories.")
        return

    rec_df = recommendations_dataframe(subset, df, id_col)

    st.write(f"Showing suggested actions for **{subset['customerID'].nunique()}** customers "
             f"({len(rec_df)} individual suggestions).")

    st.dataframe(rec_df, use_container_width=True, height=450)

    st.download_button(
        "⬇️ Download recommendations as CSV", rec_df.to_csv(index=False).encode("utf-8"),
        file_name="retention_recommendations.csv", mime="text/csv",
    )

    st.divider()
    st.subheader("Recommendation Rule Reference")
    st.markdown("""
The engine evaluates each customer against explainable IF/THEN rules such as:
- **High churn risk + month-to-month contract** → consider offering a longer-term contract option
- **High churn risk + no technical support** → consider proactive technical support outreach
- **High monthly charges + high churn risk** → review plan fit and alternatives
- **Electronic check payment + high churn risk** → review payment experience and friction
- **Very new customer + high churn risk** → early-lifecycle onboarding check-in
- **Overall risk in the Critical band** → prioritize for a direct retention conversation

These rules run entirely locally in Python and do not call any external AI service.
    """)
